```cpp
#include <iostream>
#include <string>
#include <pugixml.hpp>

std::string convertMarkdownToHtml(const std::string& markdown) {
    pugi::xml_document doc;
    pugi::xml_node root;

    // Parse the Markdown input into an XML document
    if (doc.load_string(markdown.c_str())) {
        root = doc.first_child();
    } else {
        std::cerr << "Error parsing Markdown: " << doc.error_description() << std::endl;
        return "";
    }

    // Convert the XML document to HTML using pugixml's built-in XSLT support
    pugi::xml_xsl_stylesheet stylesheet;
    if (stylesheet.load_string(
        R"(
            <xsl:stylesheet xmlns:xsl="http://www.w3.org/1999/XSL/Transform" version="1.0">
                <xsl:template match="*">
                    <xsl:element name="{name()}">
                        <xsl:apply-templates select="@* | node()"/>
                    </xsl:element>
                </xsl:template>

                <xsl:template match="text()">
                    <xsl:value-of select="." disable-output-escaping="yes"/>
                </xsl:template>
            </xsl:stylesheet>
        )"
        )) {
        pugi::xml_xsl_transform transform(stylesheet);
        transform.set_source(root);
        if (transform.apply()) {
            return transform.result().node()->to_string();
        } else {
            std::cerr << "Error converting to HTML: " << transform.error_description() << std::endl;
            return "";
        }
    } else {
        std::cerr << "Error loading XSLT stylesheet" << std::endl;
        return "";
    }
}
```

